123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
126	        Collection<Owner> owners;
127	        if (lastName != null) {
128	            owners = this.clinicService.findOwnerByLastName(lastName);
129	        } else {
130	            owners = this.clinicService.findAllOwners();
131	        }
132	        if (owners.isEmpty()) {
133	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
134	        }
135	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
136	    }
137	
138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Override
140	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
141	        Owner owner = this.clinicService.findOwnerById(ownerId);
142	        if (owner == null) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
151	        validateRequiredFields(ownerFieldsDto);
152	        HttpHeaders headers = new HttpHeaders();
153	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
154	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
155	        LocalDate effectiveDate = owner.getRegistrationDate() == null
156	            ? LocalDate.now()
157	            : owner.getRegistrationDate();
158	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
159	        rejectWhenDailyLimitReached(owner.getRegistrationDate());
160	        rejectWhenCityAtCapacity(owner.getCity());
161	        applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
162	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
163	        rejectDuplicateTelephone(telephone);
164	        owner.setTelephone(telephone);
165	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
166	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
167	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
168	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
169	        this.clinicService.saveOwner(owner);
170	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
171	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
172	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
173	            ownerDto.getMembershipLevel());
174	        headers.setLocation(UriComponentsBuilder.newInstance()
175	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
176	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
177	    }
178	
179	    /**
180	     * Builds the next customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>} where CITY3 is the
181	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three letters
182	     * of the owner's last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more
183	     * than the number of owners already in that city (e.g. {@code MAD-SMI-0007}).
184	     *
185	     * @param city     the owner's city
186	     * @param lastName the owner's last name
187	     * @return the assigned customer code
188	     */
189	    private String nextCustomerCode(String city, String lastName) {
190	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
191	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
192	        int sequence = (int) this.clinicService.findAllOwners().stream()
193	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
194	            .count() + 1;
195	        return String.format("%s-%s-%04d", city3, last3, sequence);
196	    }
197	
198	    /**
199	     * Builds the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
200	     * last two digits of the registrationDate year, zero-padded (e.g. {@code MAD-SMI-0007-M26}).
201	     *
202	     * @param customerCode     the owner's assigned customer code
203	     * @param registrationDate the owner's registration date
204	     * @return the assigned membership number
205	     */
206	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
207	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
208	    }
209	
210	    /**
211	     * Counts the existing owners that already share the given firstName and lastName, compared
212	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
213	     * the owners that pre-existed this create.
214	     *
215	     * @param firstName the new owner's first name
216	     * @param lastName  the new owner's last name
217	     * @return the number of existing namesakes
218	     */
219	    private int countNamesakes(String firstName, String lastName) {
220	        return (int) this.clinicService.findAllOwners().stream()
221	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
222	                && equalsIgnoreCase(existing.getLastName(), lastName))
223	            .count();
224	    }
225	
226	    /**
227	     * Rejects creating an owner when their city already contains {@link #CITY_CAPACITY} or more
228	     * owners. Existing owners are counted case-insensitively by city, matching how the per-city
229	     * customer-code sequence is derived.
230	     *
231	     * @param city the new owner's city
232	     * @throws CityAtCapacityException if the city already holds {@link #CITY_CAPACITY} owners
233	     */
234	    private void rejectWhenCityAtCapacity(String city) {
235	        long count = this.clinicService.findAllOwners().stream()
236	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
237	            .count();
238	        if (count >= CITY_CAPACITY) {
239	            throw new CityAtCapacityException(city);
240	        }
241	    }
242	
243	    /**
244	     * Rejects creating an owner once {@link #DAILY_OWNER_LIMIT} or more owners already carry the
245	     * given business day as their {@code registrationDate}. The day is the owner's adjusted,
246	     * business-day registration date, so the limit is enforced per business day and weekend
247	     * requests count against the Monday they roll forward to.
248	     *
249	     * @param registrationDate the owner's adjusted (business-day) registration date
250	     * @throws DailyOwnerLimitException if {@link #DAILY_OWNER_LIMIT} owners already carry that
251	     *                                  registration date
252	     */
253	    private void rejectWhenDailyLimitReached(LocalDate registrationDate) {
254	        long count = this.clinicService.findAllOwners().stream()
255	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
256	            .count();
257	        if (count >= DAILY_OWNER_LIMIT) {
258	            throw new DailyOwnerLimitException(registrationDate);
259	        }
260	    }
261	
262	    /**
263	     * Rolls a registration date forward onto a business day: when it falls on a Saturday or Sunday
264	     * it advances to the following Monday, otherwise it is returned unchanged. Applied to the
265	     * effective registration date (whether supplied in the request or defaulted to the server date)
266	     * so a weekend value never persists as an owner's {@code registrationDate}.
267	     *
268	     * @param date the effective registration date
269	     * @return the same date when it is a weekday, otherwise the next Monday
270	     */
271	    private LocalDate toBusinessDay(LocalDate date) {
272	        return switch (date.getDayOfWeek()) {
273	            case SATURDAY -> date.plusDays(2);
274	            case SUNDAY -> date.plusDays(1);
275	            default -> date;
276	        };
277	    }
278	
279	    private boolean equalsIgnoreCase(String a, String b) {
280	        return a == null ? b == null : a.equalsIgnoreCase(b);
281	    }
282	
283	    /**
284	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
285	     * offending field so the client learns about all of them at once.
286	     *
287	     * @param ownerFieldsDto the submitted owner fields
288	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
289	     *                                     missing or blank
290	     */
291	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
292	        List<String> errors = new ArrayList<>();
293	        if (isBlank(ownerFieldsDto.getFirstName())) {
294	            errors.add("firstName");
295	        }
296	        if (isBlank(ownerFieldsDto.getLastName())) {
297	            errors.add("lastName");
298	        }
299	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
300	            errors.add("address");
301	        }
302	        if (isBlank(ownerFieldsDto.getCity())) {
303	            errors.add("city");
304	        }
305	        if (isBlank(ownerFieldsDto.getTelephone())) {
306	            errors.add("telephone");
307	        }
308	        if (!errors.isEmpty()) {
309	            throw new MissingOwnerFieldsException(errors);
310	        }
311	    }
312	
313	    private boolean isBlank(String value) {
314	        return value == null || value.isBlank();
315	    }
316	
317	    /**
318	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
319	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
320	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
321	     * followed by 8 to 15 digits.
322	     *
323	     * @param telephone the raw telephone value as submitted
324	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
325	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
326	     */
327	    private String normalizeTelephone(String telephone) {
328	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
329	        String nationalSignificantNumber;
330	        if (cleaned.startsWith("+")) {
331	            nationalSignificantNumber = cleaned.substring(1);
332	        } else {
333	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
334	            nationalSignificantNumber = "61" + national;
335	        }
336	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
337	            throw new InvalidTelephoneException(telephone);
338	        }
339	        return "+" + nationalSignificantNumber;
340	    }
341	
342	    /**
343	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
344	     * value is treated as absent and returns {@code null}); when present the value must be a
345	     * syntactically valid address, and is stored and returned lower-cased.
346	     *
347	     * @param email the raw email value as submitted, may be {@code null}
348	     * @return the lower-cased email, or {@code null} when none was supplied
349	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
350	     */
351	    private String normalizeEmail(String email) {
352	        if (email == null || email.isBlank()) {
353	            return null;
354	        }
355	        String normalized = email.trim().toLowerCase();
356	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
357	            throw new InvalidEmailException(email);
358	        }
359	        return normalized;
360	    }
361	
362	    /**
363	     * Rejects a normalized telephone that is already used by any other owner, so telephones stay
364	     * unique across owners. Existing telephones are normalized to E.164 the same way before the
365	     * comparison, so numbers that differ only in formatting still count as duplicates.
366	     *
367	     * @param e164Telephone the E.164 telephone of the owner being created
368	     * @throws DuplicateTelephoneException if another owner already uses the same E.164 telephone
369	     */
370	    private void rejectDuplicateTelephone(String e164Telephone) {
371	        boolean inUse = this.clinicService.findAllOwners().stream()
372	            .map(Owner::getTelephone)
373	            .filter(existing -> existing != null)
374	            .map(this::toComparableTelephone)
375	            .filter(existing -> existing != null)
376	            .anyMatch(e164Telephone::equals);
377	        if (inUse) {
378	            throw new DuplicateTelephoneException(e164Telephone);
379	        }
380	    }
381	
382	    /**
383	     * Normalizes an existing owner's stored telephone to E.164 for duplicate comparison, returning
384	     * {@code null} when it cannot be normalized so a malformed legacy value is simply skipped rather
385	     * than aborting the whole create.
386	     */
387	    private String toComparableTelephone(String telephone) {
388	        try {
389	            return normalizeTelephone(telephone);
390	        } catch (InvalidTelephoneException ex) {
391	            return null;
392	        }
393	    }
394	
395	    /**
396	     * Applies the household rule to an owner being created. An owner belongs to the same household
397	     * as an existing owner when their lastName and address both match (compared case-insensitively
398	     * with runs of whitespace collapsed to a single space).
399	     *
400	     * <p>When no such existing owner exists there is nothing to do. Otherwise the request must
401	     * deliberately opt in to sharing that household by setting {@code sharesHousehold=true}: when it
402	     * does, the new owner and every existing owner in the household are assigned the same stable
403	     * {@link #householdId(String, String) householdId}; when it does not, the create is rejected.
404	     *
405	     * @param owner            the owner being created
406	     * @param sharesHousehold  the request's {@code sharesHousehold} flag, may be {@code null}
407	     * @throws DuplicateHouseholdException if another owner shares the same lastName and address and
408	     *                                     the request did not opt in with {@code sharesHousehold=true}
409	     */
410	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
411	        String lastNameKey = toHouseholdKey(owner.getLastName());
412	        String addressKey = toHouseholdKey(owner.getAddress());
413	        List<Owner> household = this.clinicService.findAllOwners().stream()
414	            .filter(existing -> toHouseholdKey(existing.getLastName()).equals(lastNameKey)
415	                && toHouseholdKey(existing.getAddress()).equals(addressKey))
416	            .toList();
417	        if (household.isEmpty()) {
418	            return;
419	        }
420	        if (!Boolean.TRUE.equals(sharesHousehold)) {
421	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
422	        }
423	        String householdId = householdId(lastNameKey, addressKey);
424	        owner.setHouseholdId(householdId);
425	        for (Owner existing : household) {
426	            if (!householdId.equals(existing.getHouseholdId())) {
427	                existing.setHouseholdId(householdId);
428	                this.clinicService.saveOwner(existing);
429	            }
430	        }
431	    }
432	
433	    /**
434	     * Derives the stable, shared household identifier for a household, formatted {@code HH-<HEX12>}
435	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the normalized
436	     * lastName and address keys. Being a pure function of the household, every owner in it derives
437	     * the same value regardless of creation order.
438	     *
439	     * @param lastNameKey the normalized household lastName key
440	     * @param addressKey  the normalized household address key
441	     * @return the household identifier
442	     */
443	    private String householdId(String lastNameKey, String addressKey) {
444	        try {
445	            byte[] digest = MessageDigest.getInstance("SHA-256")
446	                .digest((lastNameKey + "|" + addressKey).getBytes(StandardCharsets.UTF_8));
447	            StringBuilder hex = new StringBuilder(digest.length * 2);
448	            for (byte b : digest) {
449	                hex.append(String.format("%02x", b));
450	            }
451	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
452	        } catch (NoSuchAlgorithmException ex) {
453	            throw new IllegalStateException("SHA-256 not available", ex);
454	        }
455	    }
456	
457	    /**
458	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
459	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
460	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
461	     * string.
462	     */
463	    private String toHouseholdKey(String value) {
464	        if (value == null) {
465	            return "";
466	        }
467	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
468	    }
469	
470	    /**
471	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
472	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
473	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
474	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
475	     * value, or one that is blank once trimmed, normalizes to an empty string.
476	     *
477	     * @param address the raw address value as submitted, may be {@code null}
478	     * @return the normalized address, or an empty string when none was supplied
479	     */
480	    private String normalizeAddress(String address) {
481	        if (address == null) {
482	            return "";
483	        }
484	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
485	        if (collapsed.isEmpty()) {
486	            return "";
487	        }
488	        String[] tokens = collapsed.split(" ");
489	        StringBuilder normalized = new StringBuilder(collapsed.length());
490	        for (int i = 0; i < tokens.length; i++) {
491	            if (i > 0) {
492	                normalized.append(' ');
493	            }
494	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
495	        }
496	        return normalized.toString();
497	    }
