499	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
500	    @Override
501	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
502	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
503	        if (currentOwner == null) {
504	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
505	        }
506	        currentOwner.setAddress(ownerFieldsDto.getAddress());
507	        currentOwner.setCity(ownerFieldsDto.getCity());
508	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
509	        currentOwner.setLastName(ownerFieldsDto.getLastName());
510	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
511	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
512	        this.clinicService.saveOwner(currentOwner);
513	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
514	    }
