516	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
517	    @Transactional
518	    @Override
519	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
520	        Owner owner = this.clinicService.findOwnerById(ownerId);
521	        if (owner == null) {
522	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
523	        }
524	        this.clinicService.deleteOwner(owner);
525	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
526	    }
